using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MagistralReplicationAction", menuName = "Data/Battle/Battle Actions/Orion/MagistralReplication Action")]
public class MagistralReplicationAction : ChooseDiceAction
{
	[Header("Action Instance Reference")]
	[SerializeField]
	private InvokeAction invokeAction;

	[Header("Astrium Requirement")]
	[SerializeField]
	private BattleActionWithMinimumAstriumAction magistralReplicationLogicAction;

	[Header("Astrium Decrease")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[SerializeField]
	private int decreaseAstriumAmount;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public BattleActionWithMinimumAstriumAction MagistralReplicationLogicAction => magistralReplicationLogicAction;

	public PlayerEffectsList PlayerEffectsList => playerEffectsList;

	public int DecreaseAstriumAmount => decreaseAstriumAmount;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (!magistralReplicationLogicAction.CheckAstriumAmount(0))
		{
			return false;
		}
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		DiceInstance diceInstance = diceList.First();
		diceInstance.SetDiceState(DiceState.ReturningToHandAfterTargetSpace);
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		Dice dice = diceInstance.Dice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		dice.SetDiceFaces(diceInstance.Dice.CopyDiceFacesAsNewInstances());
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			dice.GetDiceFaces()[i].KeepChanges = false;
			dice.GetDiceFaces()[i].KeepChangesForBattle = true;
		}
		invokeAction.Spawn3DDice(dice, amount, enableExternalRemoveAfterBattle: true, externalRemoveAfterBattle: true);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator VFXCoroutine(int amount, GameObject source)
	{
		PlaySFX();
		SpawnVFXOnPlayerPosition(4f);
		DiceInstance diceToCopyDiceInstance = diceList.First();
		diceToCopyDiceInstance.SetDiceState(DiceState.ReturningToHandAfterTargetSpace);
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		yield return new WaitForSeconds(vfxDelay);
		Dice dice = diceToCopyDiceInstance.Dice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		dice.SetDiceFaces(diceToCopyDiceInstance.Dice.CopyDiceFacesAsNewInstances());
		DiceFace[] diceFaces = dice.GetDiceFaces();
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			diceFaces[i].NewBattleAction = dice.GetDiceFaces()[i].BattleAction;
			diceFaces[i].NewSecondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
			diceFaces[i].NewActionValue = dice.GetDiceFaces()[i].ActionValue;
			diceFaces[i].NewSecondActionValue = dice.GetDiceFaces()[i].SecondActionValue;
		}
		dice.RemoveAfterBattle = true;
		invokeAction.Spawn3DDice(dice, amount, enableExternalRemoveAfterBattle: true, externalRemoveAfterBattle: true);
		ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().DecreaseEffect(playerEffectsList.AstriumEffect, decreaseAstriumAmount);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}
}
